		<div class="elementor-element elementor-element-8cfae67 e-flex e-con-boxed e-con e-parent" data-id="8cfae67" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
